"""Post one AI review on a pull request. Standard library only. Never fails CI."""

import json
import os
import re
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

SECRET_NAME = "AI_REVIEW_API_KEY"
MAX_DIFF_CHARS = 60000
MAX_INLINE_COMMENTS = 15
SEVERITY_ORDER = {"security": 0, "bug": 1, "suggestion": 2, "nit": 3}
HUNK_RE = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")

SKIP_DIRECTORIES = {"dist", "build", "vendor", "node_modules"}
SKIP_SUFFIXES = (
    ".png", ".jpg", ".jpeg", ".gif", ".webp", ".ico", ".bmp", ".tiff", ".svg",
    ".pdf", ".zip", ".gz", ".tar", ".woff", ".woff2", ".ttf", ".eot",
)
LOCKFILES = {
    "package-lock.json", "yarn.lock", "pnpm-lock.yaml", "bun.lockb", "poetry.lock",
    "pipfile.lock", "uv.lock", "cargo.lock", "go.sum", "gemfile.lock", "composer.lock",
}
PROVIDER_BASES = {
    "openai": "https://api.openai.com/v1",
    "ollama": "http://localhost:11434/v1",
    "opencode": "https://opencode.ai/zen/v1",
}
FALLBACK_PROMPT = (
    "Review this pull request for bugs, security problems, error handling and "
    "breaking changes. Ignore style. Do not invent problems. Return at most 10 "
    "short comments, each with a fix."
)


# ---------------------------------------------------------------------------
# HTTP
# ---------------------------------------------------------------------------

def http(method, url, headers=None, body=None):
    """Perform one request. Returns (status, bytes); HTTP errors are values."""
    payload = json.dumps(body).encode("utf-8") if body is not None else None
    request = urllib.request.Request(url, data=payload, headers=headers or {}, method=method)
    try:
        response = urllib.request.urlopen(request, timeout=60)
        return getattr(response, "status", 200), response.read()
    except urllib.error.HTTPError as error:
        return error.code, error.read()


def http_retry(method, url, headers=None, body=None, attempts=4):
    """Retry 429 and 5xx with exponential backoff."""
    for attempt in range(attempts):
        status, data = http(method, url, headers, body)
        if status == 429 or 500 <= status < 600:
            if attempt + 1 < attempts:
                time.sleep(2 ** attempt)
                continue
        return status, data
    return status, data


def decode_json(data):
    try:
        return json.loads(data.decode("utf-8", "replace"))
    except (ValueError, AttributeError):
        return {}


# ---------------------------------------------------------------------------
# Structured output
# ---------------------------------------------------------------------------

def review_schema(upper_case=False):
    """Schema for {summary, comments:[{path,line,severity,comment}]}."""
    kind = lambda name: name.upper() if upper_case else name
    severities = ["bug", "security", "suggestion", "nit"]
    comment = {
        "type": kind("object"),
        "properties": {
            "path": {"type": kind("string")},
            "line": {"type": kind("integer")},
            "severity": {"type": kind("string"), "enum": severities},
            "comment": {"type": kind("string")},
        },
        "required": ["path", "line", "severity", "comment"],
    }
    return {
        "type": kind("object"),
        "properties": {
            "summary": {"type": kind("string")},
            "comments": {"type": kind("array"), "items": comment},
        },
        "required": ["summary", "comments"],
    }


def _balanced_strings(text):
    """Yield balanced {...} substrings, ignoring braces inside JSON strings."""
    start = None
    depth = 0
    quoted = False
    escaped = False
    for index, char in enumerate(text):
        if quoted:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                quoted = False
            continue
        if char == '"':
            quoted = True
        elif char == "{":
            if depth == 0:
                start = index
            depth += 1
        elif char == "}" and depth:
            depth -= 1
            if depth == 0 and start is not None:
                yield text[start:index + 1]
                start = None


def extract_json(text):
    """Parse a JSON object, including one wrapped in prose or code fences."""
    if not text:
        return {}
    raw = str(text).strip()
    if raw.startswith("```"):
        raw = re.sub(r"^```(?:json)?\s*", "", raw)
        raw = re.sub(r"\s*```$", "", raw).strip()
    candidates = [raw]
    first, last = raw.find("{"), raw.rfind("}")
    if first >= 0 and last > first:
        candidates.append(raw[first:last + 1])
    candidates.extend(_balanced_strings(raw))
    for candidate in candidates:
        try:
            value = json.loads(candidate)
        except (ValueError, TypeError):
            continue
        if isinstance(value, dict):
            return value
    return {}


def call_gemini(prompt, model, key):
    url = "https://generativelanguage.googleapis.com/v1beta/models/{0}:generateContent".format(
        urllib.parse.quote(model, safe="")
    )
    body = {
        "contents": [{"parts": [{"text": prompt}]}],
        "generationConfig": {
            "responseMimeType": "application/json",
            "responseSchema": review_schema(upper_case=True),
        },
    }
    status, data = http_retry("POST", url, {"Content-Type": "application/json", "x-goog-api-key": key}, body)
    if status >= 400:
        return {}
    payload = decode_json(data)
    candidates = payload.get("candidates") or []
    if not candidates:
        return {}
    parts = (candidates[0].get("content") or {}).get("parts") or []
    return extract_json(parts[0].get("text", "") if parts else "")


def call_anthropic(prompt, model, key):
    url = "https://api.anthropic.com/v1/messages"
    body = {
        "model": model,
        "max_tokens": 4096,
        "tools": [{
            "name": "submit_review",
            "description": "Submit the pull request review as structured JSON.",
            "input_schema": review_schema(),
        }],
        "tool_choice": {"type": "tool", "name": "submit_review"},
        "messages": [{"role": "user", "content": prompt}],
    }
    headers = {
        "Content-Type": "application/json",
        "x-api-key": key,
        "anthropic-version": "2026-10-21",
    }
    status, data = http_retry("POST", url, headers, body)
    if status >= 400:
        return {}
    blocks = decode_json(data).get("content") or []
    for block in blocks:
        if block.get("type") == "tool_use" and block.get("name") == "submit_review":
            value = block.get("input")
            return value if isinstance(value, dict) else extract_json(value)
    text = " ".join(block.get("text", "") for block in blocks if block.get("type") == "text")
    return extract_json(text)


def call_openai_style(provider, prompt, model, base_url, key):
    url = (base_url or PROVIDER_BASES.get(provider, "")).rstrip("/") + "/chat/completions"
    headers = {"Content-Type": "application/json"}
    if key:
        headers["Authorization"] = "Bearer " + key
    body = {
        "model": model,
        "messages": [
            {"role": "system", "content": "Reply with a single JSON object and nothing else."},
            {"role": "user", "content": prompt},
        ],
        "response_format": {"type": "json_object"},
    }
    status, data = http_retry("POST", url, headers, body)
    if status == 400:
        body.pop("response_format", None)
        status, data = http("POST", url, headers, body)
    if status >= 400:
        return {}
    choices = decode_json(data).get("choices") or []
    if not choices:
        return {}
    return extract_json((choices[0].get("message") or {}).get("content", ""))


def ask_model(provider, prompt, model, base_url, key):
    if provider == "gemini":
        return call_gemini(prompt, model, key)
    if provider == "anthropic":
        return call_anthropic(prompt, model, key)
    return call_openai_style(provider, prompt, model, base_url, key)


# ---------------------------------------------------------------------------
# Diff parsing
# ---------------------------------------------------------------------------

def _clean_path(value):
    value = value.strip().split("\t")[0].strip('"')
    if value.startswith(("a/", "b/")):
        value = value[2:]
    return value


def _numbered(number, line):
    prefix = "{0:>6}".format(number) if number is not None else "     -"
    return prefix + " | " + line


def parse_diff(diff_text):
    """Return (files, blocks).

    files maps a new-side path to the set of valid new-side line numbers.
    blocks is an ordered list of (path, lines) for rendering a filtered diff.
    """
    files = {}
    blocks = []
    current_path = ""
    in_hunk = False
    old_left = 0
    new_left = 0
    new_line = 0

    for line in (diff_text or "").splitlines():
        if not in_hunk:
            if line.startswith("diff --git "):
                fields = line.split(" ", 3)
                current_path = _clean_path(fields[3]) if len(fields) > 3 else ""
                blocks.append([current_path, [line]])
                continue
            if line.startswith("rename to "):
                if not current_path:
                    current_path = _clean_path(line[len("rename to "):])
                blocks.append([current_path, [line]])
                continue
            if line.startswith("+++ "):
                path = line[4:].strip()
                if path != "/dev/null" and not current_path:
                    current_path = _clean_path(path)
                blocks.append([current_path, [line]])
                continue
            if line.startswith("--- ") or line.startswith("new file mode") or line.startswith("deleted file mode"):
                if blocks:
                    blocks[-1][1].append(line)
                else:
                    blocks.append([None, [line]])
                continue

        hunk = HUNK_RE.match(line)
        if hunk:
            in_hunk = True
            old_left = int(hunk.group(2)) if hunk.group(2) is not None else 1
            new_left = int(hunk.group(4)) if hunk.group(4) is not None else 1
            new_line = int(hunk.group(3))
            files.setdefault(current_path, set())
            if not blocks:
                blocks.append([current_path, []])
            blocks[-1][1].append(line)
            continue

        if in_hunk:
            prefix = line[:1]
            if prefix == " ":
                files.setdefault(current_path, set()).add(new_line)
                blocks[-1][1].append(_numbered(new_line, line))
                new_line += 1
                old_left -= 1
                new_left -= 1
            elif prefix == "+":
                files.setdefault(current_path, set()).add(new_line)
                blocks[-1][1].append(_numbered(new_line, line))
                new_line += 1
                new_left -= 1
            elif prefix == "-":
                blocks[-1][1].append(_numbered(None, line))
                old_left -= 1
            else:
                blocks[-1][1].append(_numbered(None, line))
            if old_left <= 0 and new_left <= 0:
                in_hunk = False
        else:
            if not blocks:
                blocks.append([None, []])
            blocks[-1][1].append(line)

    return files, blocks


def should_skip(path):
    name = (path or "").replace("\\", "/")
    parts = name.split("/")
    if any(part in SKIP_DIRECTORIES for part in parts):
        return True
    filename = parts[-1].lower()
    return filename in LOCKFILES or ".min." in filename or filename.endswith(SKIP_SUFFIXES)


def filtered_diff(blocks, files, skipped):
    """Render only non-skipped files, listing what was left out."""
    kept = []
    for path, lines in blocks:
        if path is not None and (should_skip(path) or not files.get(path)):
            if path and path not in skipped:
                skipped.append(path)
            continue
        kept.extend(lines)
    text = "\n".join(kept)
    if len(text) > MAX_DIFF_CHARS:
        text = text[:MAX_DIFF_CHARS]
        skipped.append("diff truncated to {0} characters".format(MAX_DIFF_CHARS))
    return text


def load_prompt():
    try:
        return Path(__file__).with_name("prompt.md").read_text(encoding="utf-8")
    except OSError:
        return FALLBACK_PROMPT


def build_prompt(diff_text, extra, skipped):
    parts = [load_prompt()]
    if extra:
        parts.append("Extra rules from the repository owner:\n" + extra)
    if skipped:
        parts.append("Skipped from review: " + ", ".join(skipped))
    parts.append("Pull request diff (new-side line numbers at left; removed lines unnumbered):\n" + diff_text)
    return "\n\n".join(parts)


# ---------------------------------------------------------------------------
# Review assembly and posting
# ---------------------------------------------------------------------------

def normalize_result(result):
    if not isinstance(result, dict):
        return "", []
    summary = result.get("summary")
    summary = summary if isinstance(summary, str) else ""
    comments = []
    for item in result.get("comments") or []:
        if not isinstance(item, dict):
            continue
        try:
            line = int(item.get("line"))
        except (TypeError, ValueError):
            continue
        severity = str(item.get("severity") or "suggestion").lower()
        if severity not in SEVERITY_ORDER:
            severity = "suggestion"
        path = str(item.get("path") or "")
        text = str(item.get("comment") or "")
        if path and text:
            comments.append({"path": path, "line": line, "severity": severity, "comment": text})
    return summary, comments


def choose_comments(comments, files, limit=MAX_INLINE_COMMENTS):
    """Filter to valid changed lines, de-duplicate, sort by severity."""
    seen = set()
    unique = []
    for item in comments:
        key = (item["path"], item["line"], item["comment"])
        if key in seen:
            continue
        seen.add(key)
        unique.append(item)
    valid = [item for item in unique if item["line"] in files.get(item["path"], set())]
    invalid = [item for item in unique if item not in valid]
    valid.sort(key=lambda item: (
        SEVERITY_ORDER.get(item["severity"], 9), item["path"], item["line"], item["comment"]
    ))
    return valid[:limit], valid[limit:] + invalid


def review_body(summary, skipped, overflow):
    body = [summary or "No summary provided."]
    if skipped:
        body.append("Skipped from review: " + ", ".join(skipped))
    if overflow:
        body.append("Additional comments (not placed inline):")
        for item in overflow:
            body.append("- [{0}] {1}:{2} - {3}".format(
                item["severity"], item["path"], item["line"], item["comment"]
            ))
    return "\n\n".join(body)


def post_review(api, token, repo, pr_number, body, inline, overflow):
    url = "{0}/repos/{1}/pulls/{2}/reviews".format(api, repo, pr_number)
    headers = {
        "Content-Type": "application/json",
        "Authorization": "Bearer " + token,
        "Accept": "application/vnd.github+json",
    }
    github_comments = [{
        "path": item["path"],
        "line": item["line"],
        "side": "RIGHT",
        "body": item["comment"],
    } for item in inline]
    payload = {"event": "COMMENT", "body": body, "comments": github_comments}
    status, _ = http_retry("POST", url, headers, payload)
    if status == 422:
        folded = list(inline) + list(overflow)
        payload["comments"] = []
        payload["body"] = body + "\n\n" + "\n".join(
            "- [{0}] {1}:{2} - {3}".format(c["severity"], c["path"], c["line"], c["comment"])
            for c in folded
        )
        status, _ = http("POST", url, headers, payload)
    return status


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

def annotation(level, message, key=""):
    safe = str(message)
    if key:
        safe = safe.replace(key, "[REDACTED]")
    sys.stdout.write("::{0}::reviewer: {1}\n".format(level, safe.replace("\n", " ")))


def main():
    key = os.environ.get(SECRET_NAME, "")
    if not key:
        return 0  # fork PR: no secrets are available; skip quietly

    provider = os.environ.get("PROVIDER", "gemini")
    model = os.environ.get("MODEL", "gemini-2.5-flash")
    base_url = os.environ.get("BASE_URL", "")
    extra = os.environ.get("EXTRA_INSTRUCTIONS", "")
    token = os.environ.get("GITHUB_TOKEN", "")
    repo = os.environ.get("GITHUB_REPOSITORY", "")
    pr_number = os.environ.get("PR_NUMBER", "")
    api = os.environ.get("GITHUB_API_URL", "https://api.github.com").rstrip("/")

    if not repo or not pr_number:
        annotation("warning", "missing repository or pull request number")
        return 0

    headers = {
        "Authorization": "Bearer " + token,
        "Accept": "application/vnd.github+json",
    }
    status, data = http_retry("GET", "{0}/repos/{1}/pulls/{2}".format(api, repo, pr_number), headers)
    if status >= 400:
        annotation("error", "could not read pull request metadata (HTTP {0})".format(status))
        return 0

    diff_headers = dict(headers)
    diff_headers["Accept"] = "application/vnd.github.v3.diff"
    status, data = http_retry("GET", "{0}/repos/{1}/pulls/{2}".format(api, repo, pr_number), diff_headers)
    if status >= 400:
        annotation("error", "could not read pull request diff (HTTP {0})".format(status))
        return 0

    files, blocks = parse_diff(data.decode("utf-8", "replace"))
    skipped = []
    diff_text = filtered_diff(blocks, files, skipped)
    prompt = build_prompt(diff_text, extra, skipped)
    result = ask_model(provider, prompt, model, base_url, key)
    summary, comments = normalize_result(result)
    inline, overflow = choose_comments(comments, files)
    body = review_body(summary, skipped, overflow)
    status = post_review(api, token, repo, pr_number, body, inline, overflow)
    if status >= 400:
        annotation("warning", "could not post review (HTTP {0})".format(status), key)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as error:  # never fail CI
        annotation("error", "unexpected {0}: {1}".format(type(error).__name__, error), os.environ.get(SECRET_NAME, ""))
        sys.exit(0)
